        }
        let cost = CellTaskCostV2::new(CellTaskCostIdentityV2 {
            task_digest: config.task_digest,
            source_digest: config.manifest.source_digest,
        })
        .map_err(|_| CellGenerationErrorV2::InvalidBinding)?;
